using System;using System.Diagnostics;using System.IO;using System.Threading;using System.Windows.Forms;using System.Collections.Generic;
class ClosingTest {
 [STAThread]static int Main(string[] args){if((args.Length>0&&args[0]=="fixture")||Path.GetFileName(Application.ExecutablePath)=="SameName.exe"){var form=new Form{Text="Stackify close test",ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,Left=-30000,Top=-30000};form.Shown+=delegate{File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ready"),"");};if(args.Length>1)form.FormClosing+=delegate(object s,FormClosingEventArgs e){e.Cancel=true;};Application.Run(form);return 0;}
 var processes=new List<Process>();string root=Path.Combine(Path.GetTempPath(),"StackifyCloseTest-"+Guid.NewGuid().ToString("N"));try {string[] paths=new string[3];for(int i=0;i<3;i++){string folder=Path.Combine(root,i.ToString());Directory.CreateDirectory(folder);paths[i]=Path.Combine(folder,"SameName.exe");File.Copy(Application.ExecutablePath,paths[i]);processes.Add(Process.Start(new ProcessStartInfo(paths[i],i==2?"fixture cancel":"fixture"){UseShellExecute=false}));}for(int attempt=0;attempt<50;attempt++){if(File.Exists(Path.Combine(root,"0","ready"))&&File.Exists(Path.Combine(root,"1","ready"))&&File.Exists(Path.Combine(root,"2","ready")))break;Thread.Sleep(100);}int sent=AppClosing.Close(new[]{paths[0]});if(sent!=1||!processes[0].WaitForExit(3000))throw new Exception("Selected app did not close");if(processes[1].HasExited||processes[2].HasExited)throw new Exception("Unselected app was closed");sent=AppClosing.Close(new[]{paths[2]});Thread.Sleep(300);if(sent!=1||processes[2].HasExited)throw new Exception("App cancellation was not respected");int launched=AppLaunching.Launch(new[]{paths[0],paths[1]});if(launched!=1)throw new Exception("Launch must only open the closed app");Thread.Sleep(400);if(AppLaunching.Launch(new[]{paths[0],paths[1]})!=0)throw new Exception("Launch must skip running apps");AppClosing.Close(new[]{paths[0]});Console.WriteLine("PASS: launch opens only missing apps and avoids duplicates; selected app closes; same executable name in another folder stays open; cancelled close stays open.");return 0;}catch(Exception ex){Console.WriteLine("FAIL: "+ex.Message);return 1;}finally{foreach(var extra in Process.GetProcessesByName("SameName"))using(extra)try{if(extra.MainModule.FileName.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&!extra.HasExited){extra.Kill();extra.WaitForExit(3000);}}catch{}foreach(var p in processes){try{if(!p.HasExited){p.Kill();p.WaitForExit(3000);}}catch{}p.Dispose();}}
 }
}

